const topic = String(query ?? '').toLowerCase();
if (/password|login|sign.?in|account access|access|вход|войти|парол/.test(topic)) return 'Access: use the password reset page. Never share passwords or verification codes.';
if (/bill|payment|invoice|оплат|сч[её]т/.test(topic)) return 'Billing: provide the invoice date and a masked transaction reference; never send full card details.';
if (/error|technical|broken|ошиб|не работает/.test(topic)) return 'Technical: provide the error text, approximate time, and affected feature. Do not include secrets.';
return 'General: describe the expected result and what happened. A support specialist can follow up.';

const issue = String(query ?? '').toLowerCase();
const urgent = /outage|service down|blocked|unavailable|can't access|cannot access|unable to access|can't log in|cannot log in|unable to log in|login failed|account access|urgent|time-critical|срочно|блокир|недоступ|не работает у всех|не могу войти|не уда[её]тся войти|не могу зайти/.test(issue);
return JSON.stringify({ urgency: urgent ? 'high' : 'normal', rule: urgent ? 'Add to the escalation queue for human review.' : 'Keep in the normal support queue.' });

let parsed = $json.output ?? $json;
if (typeof parsed === 'string') {
  const match = parsed.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('Agent response did not contain JSON');
  parsed = JSON.parse(match[0]);
}
const allowed = ['access', 'billing', 'technical', 'general'];
if (!allowed.includes(parsed.category) || !['high', 'normal'].includes(parsed.urgency)) throw new Error('Agent returned an invalid category or urgency');
const input = $('Incoming Webhook').item.json.body ?? $('Incoming Webhook').item.json;
return { json: { createdAt: new Date().toISOString(), message: String(input.message ?? ''), category: parsed.category, urgency: parsed.urgency, summary: String(parsed.summary ?? ''), reply: String(parsed.reply ?? '') } };
